<?php
declare(strict_types=1);
require __DIR__ . '/app/bootstrap.php';
$requestHost = strtolower((string)($_SERVER['HTTP_HOST'] ?? ''));
$requestHost = preg_replace('/:\\d+$/', '', $requestHost) ?? $requestHost;
if ($_SERVER['REQUEST_METHOD'] === 'GET' && $requestHost !== '' && !in_array($requestHost, ['localhost','127.0.0.1','::1'], true) && str_contains($requestHost, '.')) {
    try {
        $stmt = db()->prepare("SELECT COUNT(*) FROM analyses WHERE domain = ? AND action = 'blocked' AND created_at >= (NOW() - INTERVAL 2 MINUTE)");
        $stmt->execute([normalize_domain($requestHost)]);
        if ((int)$stmt->fetchColumn() > 0) { require __DIR__ . '/blocked.php'; exit; }
    } catch (Throwable $ignored) {}
}
$page = $_GET['page'] ?? 'dashboard';
if (!in_array($page, ['dashboard','activity','about'], true)) $page = 'dashboard';
function count_query(PDO $pdo, string $sql): int { return (int)$pdo->query($sql)->fetchColumn(); }
function page_title(string $page): string { return ['dashboard'=>'Resumen DNS','activity'=>'Bitácora DNS','about'=>'Estado del servicio'][$page] ?? 'GuardDNS'; }
try { $pdo = db(); } catch (Throwable $e) { $setupError = $e->getMessage(); }
